// Embeds Leaflet (JS + CSS) as strings so the map HTML works offline inside
// a WebView (iOS/Android) and a sandboxed iframe (web) without any CDN.
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const dir = require.resolve('leaflet/package.json').replace(/package\.json$/, 'dist/');
const { version } = require('leaflet/package.json');
const js = readFileSync(dir + 'leaflet.js', 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '');
const css = readFileSync(dir + 'leaflet.css', 'utf8');

const out = `// AUTO-GENERATED by scripts/build-leaflet.mjs – do not edit.
// Leaflet ${version} – BSD-2-Clause, (c) Volodymyr Agafonkin, CloudMade
/* eslint-disable */
export const LEAFLET_VERSION = ${JSON.stringify(version)};
export const LEAFLET_JS = ${JSON.stringify(js)};
export const LEAFLET_CSS = ${JSON.stringify(css)};
`;
writeFileSync(new URL('../src/map/leafletAssets.ts', import.meta.url), out);
console.log(`leafletAssets.ts written (Leaflet ${version}, ${(out.length / 1024).toFixed(0)} KB)`);
